* { box-sizing: border-box; }

body {
    margin: 0;
    padding: 16px 24px;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    color: #222;
    background: #fafafa;
}

header h1 { margin: 0 0 4px; font-size: 22px; }
.subtitle { margin: 0 0 12px; color: #666; font-size: 13px; }

/* Side by side, horizontally: chart left, table right. No wrapping. */
.dashboard {
    display: flex;
    flex-direction: row;
    flex-wrap: nowrap;
    align-items: flex-start;
    gap: 20px;
}

.panel {
    background: #fff;
    border: 1px solid #e3e3e3;
    border-radius: 6px;
    padding: 12px;
}
.panel h2 { margin: 0 0 8px; font-size: 16px; }

.chart-panel { flex: 0 0 auto; }
.table-panel { flex: 1 1 auto; min-width: 380px; }

#chart svg { display: block; }

.bubble {
    stroke: #fff;
    stroke-width: 1px;
    cursor: pointer;
    opacity: 0.88;
}
.bubble:hover { opacity: 1; stroke: #333; }
.bubble.selected,
.bubble.highlighted {
    opacity: 1;
    stroke: #000;
    stroke-width: 3px;
}

.bubble-label {
    fill: #fff;
    font-weight: 600;
    text-anchor: middle;
    dominant-baseline: central;
    pointer-events: none;   /* hover/click go to the circle underneath */
    user-select: none;
}

.legend-item text { font-size: 12px; fill: #333; dominant-baseline: central; }

/* Tooltip: hidden by opacity, shown with the .visible class. */
.tooltip {
    position: absolute;
    padding: 10px;
    background: rgba(0, 0, 0, 0.8);
    color: white;
    border-radius: 4px;
    pointer-events: none;
    opacity: 0;
    transition: opacity 0.2s;
    z-index: 1000;
    font-size: 14px;
    line-height: 1.4;
}
.tooltip.visible { opacity: 1; }

#table-container {
    overflow-y: auto;
    border-top: 1px solid #eee;
}

#data-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 13px;
}
#data-table th {
    position: sticky;
    top: 0;
    background: #f5f5f5;
    padding: 8px 10px;
    text-align: left;
    border-bottom: 2px solid #ddd;
    font-weight: bold;
    z-index: 1;
}
#data-table td {
    padding: 6px 10px;
    border-bottom: 1px solid #eee;
}
#data-table td.num, #data-table th.num { text-align: right; }
#data-table tbody tr { cursor: pointer; }
#data-table tbody tr:hover { background: #f4f8fb; }
#data-table tbody tr.selected,
#data-table tbody tr.highlighted {
    background: #fff3b0 !important;
    font-weight: 600;
    outline: 2px solid #f0b400;
}
.swatch {
    display: inline-block;
    width: 10px;
    height: 10px;
    border-radius: 50%;
    margin-right: 6px;
    vertical-align: middle;
}

