    }

    d3.csv(CONFIG.dataPath)
        .then(raw => {
            if (!raw || raw.length === 0) throw new Error('empty CSV');
            render(raw);
        })
        .catch(err => {
            console.warn('d3.csv(' + CONFIG.dataPath + ') failed (' + err + '); using embedded rows.');
            render(EMBEDDED_ROWS);
        });
})();

