python3 - <<'EOF'
p='assets/app/visualization.js'
s=open(p).read()
start=s.index("        // Sector anchors on a ring")
end=s.index("        for (let attempt = 0; attempt < 10; attempt++) {")
new='''        // Sector anchors: one circle per sector, sized to that sector's packed cluster
        // (sum of its bubble areas at ~62% density) plus a small gap, tightly packed
        // with d3.packSiblings (deterministic: largest first, ties by name) and centred
        // on the plot centre. Neighbouring clusters touch without mixing, whatever the
        // number of sectors or how unequal they are.
        function anchorsFor(scale) {
            const gap = 8;
            const circles = sectors.map(s => {
                const sq = d3.sum(nodes, (d, i) => d.sector === s ? Math.pow(relR[i] * scale, 2) : 0);
                return {sector: s, r: Math.sqrt(sq / 0.62) + gap / 2};
            }).sort((a, b) => (b.r - a.r) || d3.ascending(a.sector, b.sector));
            d3.packSiblings(circles);
            const enc = d3.packEnclose(circles);
            return new Map(circles.map(c => [c.sector, {x: cx + c.x - enc.x, y: cy + c.y - enc.y}]));
        }

'''
s=s[:start]+new+s[end:]
s=s.replace("    const EMBEDDED_ROWS = __EMBEDDED_ROWS__;","    const EMBEDDED_ROWS = __EMBEDDED_ROWS__;\n    // upper-cased ticker -> 'data/<price dir>/<file>.csv' (for custom price panels; unused by default)\n    const PRICE_FILES = CONFIG.priceFiles || {};")
s=s.replace(" * - Force layout is deterministic: nodes start on a fixed spiral around their\n *   sector's anchor,"," * - Force layout is deterministic: sector anchors are packed with d3.packSiblings,\n *   nodes start on a fixed spiral around their sector's anchor,")
open(p,'w').write(s)

p='scripts/build_app.py'
s=open(p).read()
s=s.replace('''    price_dirs, price_files = [], {}''','''    price_dirs, price_files, price_paths = [], {}, {}''')
s=s.replace('''                    price_files[os.path.splitext(f)[0].upper()] = f"{d}/{f}"''','''                    price_files[os.path.splitext(f)[0].upper()] = f"{d}/{f}"
    # ticker (upper case) -> app-relative path, for the rows that have a file
    for t in [x["ticker"] for x in recs]:
        if t.upper() in price_files:
            price_paths[t.upper()] = "data/" + price_files[t.upper()]''')
s=s.replace('''        "warnings": warnings,
    }''','''        "warnings": warnings,
    }, price_paths''')
s=s.replace('''    return fields, cmap, recs, {''','''    return fields, cmap, recs, {''')
s=s.replace('''    fields, cmap, recs, prof = profile(data_dir, desc)''','''    fields, cmap, recs, prof, price_paths = profile(data_dir, desc)''')
s=s.replace('''        "palette": PALETTE,
    }''','''        "palette": PALETTE,
        "priceFiles": price_paths,
    }''')
open(p,'w').write(s)
p='scripts/verify_app.py'
s=open(p).read().replace("    _, _, recs, _ = profile(","    _, _, recs, _, _ = profile(")
open(p,'w').write(s)
EOF
